const input = $input.first().json;
const data = input.body || input;

const target     = data['Target URL'] || data.target;
const vulnType   = data['Vulnerability Type'] || 'A03_Injection_SQLi';
const depth      = parseInt(data.Depth) || 2;
const authToken  = data['Auth Token'] || '';
const useArjun   = data.useArjun === true || data.useArjun === 'true'; // Читаем чекбокс

if (!target || !target.startsWith('http')) {
  throw new Error('Invalid target: ' + target);
}

// === Маппинг OWASP-категория → wordlist ===
const WORDLISTS = {
  A01_Broken_Access_Control:    '/seeds/payloads.txt',
  A03_Injection_SQLi:           '/seeds/SecLists/Fuzzing/Databases/SQLi/Generic-SQLi.txt',
  A03_Injection_XSS:            '/seeds/SecLists/Fuzzing/XSS/robot-friendly/XSS-Jhaddix.txt',
  A03_Injection_SSTI:           '/seeds/SecLists/Fuzzing/template-engines-special-vars.txt',
  A03_Injection_CMD:            '/seeds/SecLists/Fuzzing/command-injection-commix.txt',
  A03_Injection_LFI:            '/seeds/SecLists/Fuzzing/LFI/LFI-Jhaddix.txt',
  A05_Security_Misconfiguration: '/seeds/payloads.txt',
  A07_Auth_Failures:            '/seeds/SecLists/Fuzzing/Databases/SQLi/Generic-SQLi.txt',
  A10_SSRF:                     '/seeds/payloads.txt',
};

// === Человеческие названия OWASP ===
const OWASP_NAMES = {
  A01: 'Broken Access Control',
  A02: 'Cryptographic Failures',
  A03: 'Injection',
  A04: 'Insecure Design',
  A05: 'Security Misconfiguration',
  A06: 'Vulnerable and Outdated Components',
  A07: 'Identification and Authentication Failures',
  A08: 'Software and Data Integrity Failures',
  A09: 'Security Logging and Monitoring Failures',
  A10: 'Server-Side Request Forgery (SSRF)',
};

const wordlist = WORDLISTS[vulnType];
if (!wordlist) throw new Error('Unknown vuln_type: ' + vulnType);

// Извлекаем код OWASP (A01, A03, ...)
const owaspCategory = vulnType.split('_')[0];       // A03
const owaspName = OWASP_NAMES[owaspCategory] || 'Unknown';

const ts   = new Date().toISOString().replace(/[:.]/g, '-');
const slug = target.replace(/https?:\/\//, '').replace(/[^a-z0-9]/gi, '_');
const runId = `n8n_${vulnType}_${slug}_${ts}`;

const baseUrl    = (target.match(/^(https?:\/\/[^\/]+)/) || [])[1] || target;
const openApiUrl = `${baseUrl}/openapi.json`;

const config = {
  runId,
  target, vulnType, depth, authToken, wordlist, useArjun,
  ts, slug,
  baseUrl, openApiUrl,
  owaspCategory,   // ← НОВОЕ
  owaspName,       // ← НОВОЕ
  baselineUrl: `${target}${target.includes('?') ? '&' : '?'}id=1`,
  configFile:      `/results/${runId}_config.json`,
  baselineFile:    `/results/${runId}_baseline.json`,
  endpointsFile:   `/results/${runId}_endpoints.json`,
  arjunFile:       `/results/${runId}_arjun.json`,
  dictResultsFile: `/results/${runId}_dict_results.json`,
  schemaResultsFile: `/results/${runId}_schema_results.json`,
  reportFile:      `/results/report_${runId}.json`,

  katanaOut:       `/results/${runId}_katana.txt`,
  linkfinderOut:   `/results/${runId}_linkfinder.json`,
  puppeteerOut:    `/results/${runId}_puppeteer.json`,
  schemathesisOut: `/results/${runId}_schemathesis.xml`,

  startTime: Date.now(),
};

const fs = require('fs');
try {
  fs.writeFileSync(config.configFile, JSON.stringify(config, null, 2));
  console.log('Config saved:', config.configFile);
  console.log('RunId:', runId);
  console.log('OWASP:', owaspCategory, '-', owaspName);
} catch (e) {
  console.error('Config write failed:', e.message);
}

require('fs').writeFileSync('/results/status.json', JSON.stringify({ status: 'RUNNING', target: target }));

return [{ json: config }];

const cfg = $('Validate Config').first().json;
const resp = $input.first().json;
const fs = require('fs');

const rawBody = resp.body ?? resp.data ?? '';
let bodyStr = '';
if (typeof rawBody === 'string') {
  bodyStr = rawBody;
} else if (rawBody && typeof rawBody === 'object') {
  bodyStr = JSON.stringify(rawBody);
}

const status = resp.statusCode || resp.status || 0;

// Длина в БАЙТАХ, как у ffuf/wfuzz — берём из content-length, fallback на длину строки
const clHeader = resp.headers?.['content-length'];
const length = clHeader ? parseInt(clHeader) : Buffer.byteLength(bodyStr, 'utf8');

const baseline = {
  url: cfg.baselineUrl,
  status: status,
  length: length,
  timestamp: new Date().toISOString(),
};

try {
  fs.writeFileSync(cfg.baselineFile, JSON.stringify(baseline, null, 2));
  console.log('Baseline saved:', baseline);
} catch (e) {
  console.error('baseline write failed:', e.message);
}

return [{
  json: {
    ...cfg,
    baseline,
    baselineLength: length,
    baselineStatus: status,
  }
}];

const cfg = $('Validate Config').first().json;
const fs = require('fs');

await new Promise(r => setTimeout(r, 1500));

let xhrEndpoints = [];
let formParams = [];

if (fs.existsSync(cfg.puppeteerOut)) {
  try {
    const data = JSON.parse(fs.readFileSync(cfg.puppeteerOut, 'utf8'));

    xhrEndpoints = (data.xhr || [])
      .map(r => r.url.split('?')[0])
      .filter(u => u.startsWith('http'))
      .filter((v, i, a) => a.indexOf(v) === i);

    formParams = (data.forms || [])
      .map(f => f.name)
      .filter(n => n && !n.includes('['))
      .filter((v, i, a) => a.indexOf(v) === i);
  } catch (e) {
    console.error('Puppeteer parse error:', e.message);
  }
}

console.log(`Puppeteer: ${xhrEndpoints.length} XHR, ${formParams.length} forms`);

return [{ json: {
  ...cfg,
  puppeteerXhr: xhrEndpoints,
  puppeteerForms: formParams,
}}];

const cfg = $('Validate Config').first().json;
const fs = require('fs');

let raw = '';
try {
  raw = fs.readFileSync(cfg.linkfinderOut, 'utf8');
} catch (e) {
  console.error('LinkFinder read error:', e.message);
}

const paths = raw
  .split('\n')
  .map(l => l.trim())
  .filter(l => l && !l.startsWith('Running against'))
  .filter(l => (l.startsWith('/') && !l.startsWith('//')) || l.startsWith('http'))
  .filter(l => {
    if (/^https?:\/\/(www\.)?(owasp|youtube|fonts|google|w3|testnets|ipinfo|api\.ipinfo)/i.test(l)) return false;
    if (/\.(js|css|png|jpg|jpeg|svg|woff2?|ttf|ico|map)$/i.test(l)) return false;
    return true;
  })
  .filter((v, i, a) => a.indexOf(v) === i);

console.log(`LinkFinder: ${paths.length} paths`);

return [{ json: { ...cfg, linkfinderPaths: paths }}];

const cfg = $('Validate Config').first().json;
const fs = require('fs');

await new Promise(r => setTimeout(r, 1500));

let content = '';
try { content = fs.readFileSync(cfg.katanaOut, 'utf8'); }
catch (e) { content = cfg.target + '\n'; }

const endpoints = content
  .split('\n')
  .map(l => l.trim())
  .filter(l => l && l.includes('http'))
  .filter(l => !/\.(png|jpg|jpeg|gif|css|js|mjs|jsx|ts|tsx|woff2?|ico|svg|map|ttf|eot|webp|avif|mp4|webm)$/i.test(l))
  .filter(l => {
    if (l === cfg.target) return true;
    if (l.includes('?')) return true;
    if (/\/(rest|api|admin|user|search|login|products?|sqli|xss|ssti|rce|ptrav|xxe|redirect|ping|contact|transfer)/i.test(l)) return true;
    return false;
  })
  .filter((v, i, a) => a.indexOf(v) === i);

if (!endpoints.includes(cfg.target)) endpoints.unshift(cfg.target);

console.log(`Katana: ${endpoints.length} endpoints`);

return [{ json: { ...cfg, katanaEndpoints: endpoints }}];

const cfg = $('Validate Config').first().json;
const resp = $input.first().json;

const paths = [];

try {
  const body = resp.body ?? resp.data;
  const spec = typeof body === 'string' ? JSON.parse(body) : body;

  if (spec && spec.paths) {
    for (const path of Object.keys(spec.paths)) {
      const cleanPath = path.replace(/\{[^}]+\}/g, 'FUZZ');
      paths.push(`${cfg.baseUrl}${cleanPath}`);
    }
  }
  console.log(`OpenAPI: ${paths.length} endpoints`);
} catch (e) {
  console.log('OpenAPI parse skipped:', e.message);
}

return [{ json: { ...cfg, openApiEndpoints: paths }}];

const { URL } = require('url');

const cfg = $('Validate Config').first().json;

// === ЯВНО берём данные из каждого парсера по имени ===
const katanaEndpoints  = ($('Parse katana').first().json.katanaEndpoints)     || [];
const linkfinderPaths  = ($('Parse LinkFinder').first().json.linkfinderPaths) || [];
const openApiEndpoints = ($('Parse OpenAPI').first().json.openApiEndpoints)   || [];
const puppeteerXhr     = ($('Parse Puppeteer').first().json.puppeteerXhr)     || [];
const puppeteerForms   = ($('Parse Puppeteer').first().json.puppeteerForms)   || [];

console.log(`=== MERGE DEBUG ===`);
console.log(`katana: ${katanaEndpoints.length}`);
console.log(`linkfinder: ${linkfinderPaths.length}`);
console.log(`openapi: ${openApiEndpoints.length}`);
console.log(`puppeteer xhr: ${puppeteerXhr.length}`);
console.log(`puppeteer forms: ${puppeteerForms.length}`);

let allEndpoints = [
  ...katanaEndpoints,
  ...linkfinderPaths
    .filter(p => p.startsWith('/') && !p.startsWith('//'))
    .map(p => `${cfg.baseUrl}${p}`),
  ...openApiEndpoints,
  ...puppeteerXhr,
];

const beforeFilter = allEndpoints.length;
const targetHost = new URL(cfg.baseUrl).host.toLowerCase();

allEndpoints = allEndpoints.filter(ep => {
  try {
    const u = new URL(ep);
    if (u.host.toLowerCase() !== targetHost) return false;
    if (u.pathname.startsWith('//')) return false;
    if (/\.(js|css|png|jpg|jpeg|svg|woff2?|ttf|ico|map|webp|avif|mp4|webm|json|xml)$/i.test(u.pathname)) return false;
    return true;
  } catch (e) { return false; }
}).filter((v, i, a) => a.indexOf(v) === i);

if (allEndpoints.length === 0) allEndpoints.push(cfg.target);

console.log(`After filter: ${allEndpoints.length} endpoints (was ${beforeFilter})`);

return [{ json: {
  ...cfg,
  endpoints: allEndpoints,
  puppeteerForms,
  endpointCount: allEndpoints.length,
}}];

const { URL } = require('url');
const fs = require('fs');
const cfg = $input.first().json;

// Эндпоинты уже отфильтрованы в Merge Endpoints,
// но на всякий случай фильтруем ещё раз — дешево.
const targetHost = new URL(cfg.target).host.toLowerCase();

const endpoints = (cfg.endpoints || []).filter(ep => {
  try {
    const u = new URL(ep);
    if (u.host.toLowerCase() !== targetHost) return false;
    if (/\.(js|css|png|jpg|jpeg|svg|woff2?|ttf|ico|map|webp|avif|mp4|webm|json|xml)$/i.test(u.pathname)) return false;
    return true;
  } catch (e) { return false; }
}).filter((v, i, a) => a.indexOf(v) === i);

if (endpoints.length === 0) endpoints.push(cfg.target);

const inputFile = `/results/${cfg.runId}_nuclei_input.txt`;
fs.writeFileSync(inputFile, endpoints.join('\n'));

const nucleiOut = `/results/${cfg.runId}_nuclei.jsonl`;

console.log(`Nuclei input: ${endpoints.length} endpoints → ${inputFile}`);
console.log(endpoints.join('\n'));

return [{ json: {
  ...cfg,
  nucleiInputFile: inputFile,
  nucleiOut,
}}];

const fs = require('fs');
const cfg = $('Prepare Nuclei Input').first().json;

const findings = [];

if (fs.existsSync(cfg.nucleiOut)) {
  const raw = fs.readFileSync(cfg.nucleiOut, 'utf8').trim();
  const lines = raw ? raw.split('\n') : [];

  for (const line of lines) {
    if (!line.trim()) continue;
    try {
      const r = JSON.parse(line);

      const tags = r.info?.tags || [];
      const owaspTags = tags
        .filter(t => /^a\d{2}/i.test(t))
        .map(t => t.toUpperCase().slice(0, 3));

      findings.push({
        tool: 'nuclei',
        endpoint: r.host || '',
        matchedAt: r['matched-at'] || '',
        payload: r['matched-at'] || '',
        severity: (r.info?.severity || 'unknown').toLowerCase(),
        templateId: r['template-id'] || '',
        templateName: r.info?.name || '',
        owaspTags,
        message: r.info?.description || '',
        status: 0,
        length: 0,
        time_ms: 0,
        isFailure: true,
      });
    } catch (e) {
      console.error('Nuclei parse error:', e.message, line.slice(0, 100));
    }
  }
}

console.log(`Nuclei: ${findings.length} findings`);

return [{ json: {
  ...cfg,
  nucleiResults: findings,
  nucleiStats: {
    total: findings.length,
    bySeverity: findings.reduce((acc, f) => {
      acc[f.severity] = (acc[f.severity] || 0) + 1;
      return acc;
    }, {}),
  },
}}];

const fs = require('fs');
const data = $input.first().json;

const out = {
  runId: data.runId,
  target: data.target,
  vulnType: data.vulnType,
  owaspCategory: data.owaspCategory,
  owaspName: data.owaspName,
  nuclei: {
    results: data.nucleiResults || [],
    stats: data.nucleiStats || { total: 0, bySeverity: {} },
  },
  timestamp: new Date().toISOString(),
};

const file = `/results/${data.runId}_nuclei_results.json`;
fs.writeFileSync(file, JSON.stringify(out, null, 2));

console.log(`Nuclei DONE: ${out.nuclei.results.length} findings → ${file}`);

return [{ json: { ...out, nucleiResultsFile: file } }];
